"""96 original subtractive recipes: Prophet, CS and ARP inspired voicings.
No factory preset data, ROMs or recorded samples. Engine limitations are documented.
"""
def extend(banks,patch,osc,env,route):
 P=[];C=[];A=[]
 def make(dst,prefix,name,desc,waves,amp,cut=2600,res=.15,depth=0,fe=None,**kw):
  p=patch(prefix+' '+name,desc,waves,env(*amp),cut,res,depth,env(*fe) if fe else None,**kw);dst.append(p);return p['controls']
 def p(name,desc,w,a,cut=2600,res=.15,d=0,fe=None,**kw):
  kw.setdefault('polyphony',5);kw.setdefault('voice_drift',2.3)
  return make(P,'Prophista',name,desc,w,a,cut,res,d,fe,**kw)
 def c(name,desc,w,a,cut=3200,hp=80,res=.2,d=.8,fe=None,**kw):
  # Shared serial HP/LP approximates the spectral window, not two independent CS channels.
  kw.update(filter1_type=3,filter2_type=1,filter2_cutoff=cut,filter2_resonance=res,filter2_env=d)
  kw.setdefault('filter1_velocity',.12);kw.setdefault('filter2_velocity',.7);kw.setdefault('velocity',.65)
  return make(C,'Cineista',name,desc,w,a,hp,.1,0,fe,**kw)
 def a(name,desc,w,amp,cut=2600,res=.23,d=1,fe=None,hp=45,**kw):
  kw.setdefault('mono',True);kw.setdefault('glide',0);kw.setdefault('filter1_type',1)
  kw.update(filter2_type=3,filter2_cutoff=hp,filter2_resonance=.05)
  return make(A,'Arpista',name,desc,w,amp,cut,res,d,fe,**kw)
 def pwm(ctrl,amount=.12,rate=.4):
  ctrl['lfo1_rate']=rate;route(ctrl,1,10,'osc1_shape',amount);route(ctrl,2,10,'osc2_shape',-amount*.85)
 def vibrato(ctrl,amount=.018,rate=5.2):
  ctrl.update(lfo1_rate=rate,lfo1_delay=400,lfo1_fade=280)
  route(ctrl,1,10,'osc1_fine',amount);route(ctrl,2,10,'osc2_fine',amount)
 def expression(ctrl):
  route(ctrl,5,4,'filter2_cutoff',.08);route(ctrl,6,3,'filter2_cutoff',.06)

